export function lateFee(invoice, asOf) {
  // Invalid date
  if (!isValidDate(asOf)) {
    return 0;
  }

  // Only issued or partially_paid invoices can have late fees
  if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
    return 0;
  }

  // No dueDate means can't calculate late fee
  if (!invoice.dueDate) {
    return 0;
  }

  // If not overdue, no fee
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  // Calculate days overdue
  const daysOverdue = daysBetween(invoice.dueDate, asOf);

  // Calculate due amount
  const due = balanceDue(invoice);

  // Late fee: 0.04% per day
  const feeRate = 0.04;
  const lateFeeAmount = (due * feeRate / 100) * daysOverdue;

  // Round to cents
  return roundCents(lateFeeAmount);
}

export function dashboard(invoices, asOf) {
  // Count invoices by status
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  invoices.forEach((inv) => {
    if (counts[inv.status] !== undefined) {
      counts[inv.status]++;
    }
  });

  // Calculate outstanding (issued + partially_paid invoices)
  let outstanding = 0;
  invoices.forEach((inv) => {
    if (['issued', 'partially_paid'].includes(inv.status)) {
      outstanding += balanceDue(inv);
    }
  });

  // Get overdue invoices and calculate totals
  const overdue_list = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdue_list.length,
    amount: overdue_list.reduce((sum, inv) => sum + inv.due, 0),
  };

  // Calculate top 3 customers by amount due
  const customerDue = {};
  invoices.forEach((inv) => {
    if (['issued', 'partially_paid'].includes(inv.status)) {
      const due = balanceDue(inv);
      if (due > 0) {
        if (!customerDue[inv.customerId]) {
          customerDue[inv.customerId] = 0;
        }
        customerDue[inv.customerId] += due;
      }
    }
  });

  const topCustomers = Object.entries(customerDue)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue,
    topCustomers,
  };
}

