test('lateFee respects house rules (money as cents, no throw)', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    terms: 'NET14',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv = issueInvoice(inv.value, []).value;

  // Should not throw, even with edge cases
  let fee = lateFee(inv, '2024-10-30');
  assert.ok(typeof fee === 'number');

  fee = lateFee(inv, 'invalid-date');
  assert.equal(fee, 0);

  fee = lateFee({ status: 'draft' }, '2024-10-30');
  assert.equal(fee, 0);
});

