test('dashboard with empty invoice list', () => {
  const result = dashboard([], '2024-11-01');
  assert.equal(result.counts.draft, 0);
  assert.equal(result.counts.issued, 0);
  assert.equal(result.counts.partially_paid, 0);
  assert.equal(result.counts.paid, 0);
  assert.equal(result.outstanding, 0);
  assert.equal(result.overdue.count, 0);
  assert.equal(result.overdue.amount, 0);
  assert.equal(result.topCustomers.length, 0);
});

test('dashboard counts invoices by status', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });

  let issued = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  issued = issueInvoice(issued.value, []).value;

  let paid = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-25',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  paid = issueInvoice(paid.value, []).value;
  paid = recordPayment(paid, { amount: 6050, date: '2024-10-26' }).value;

  const result = dashboard([draft.value, issued, paid], '2024-11-01');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.paid, 1);
  assert.equal(result.counts.partially_paid, 0);
});

test('dashboard calculates outstanding (issued + partially_paid)', () => {
  let inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;
  inv2 = recordPayment(inv2, { amount: 3000, date: '2024-10-21' }).value;

  const result = dashboard([inv1, inv2], '2024-11-01');
  assert.equal(result.outstanding, 6050 + 3050);
});

test('dashboard excludes draft and paid from outstanding', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });

  let issued = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  issued = issueInvoice(issued.value, []).value;

  let paid = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-25',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  paid = issueInvoice(paid.value, []).value;
  paid = recordPayment(paid, { amount: 6050, date: '2024-10-26' }).value;

  const result = dashboard([draft.value, issued, paid], '2024-11-01');
  assert.equal(result.outstanding, 6050);
});

test('dashboard calculates overdue count and amount', () => {
  let inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    terms: 'NET14',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    terms: 'NET14',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = dashboard([inv1, inv2], '2024-11-10');
  assert.equal(result.overdue.count, 2);
  assert.equal(result.overdue.amount, 6050 + 6050);
});

test('dashboard top customers sorted by amount due', () => {
  let inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  let inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  inv3 = issueInvoice(inv3.value, []).value;

  const result = dashboard([inv1, inv2, inv3], '2024-11-01');
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[1].customerId, 'C-003');
  assert.equal(result.topCustomers[2].customerId, 'C-002');
});

test('dashboard limits top customers to 3', () => {
  let invoices = [];
  for (let i = 1; i <= 5; i++) {
    let inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2024-10-15',
      lines: [{ sku: 'STICKER', qty: 5 }],
    });
    inv = issueInvoice(inv.value, []).value;
    invoices.push(inv);
  }

  const result = dashboard(invoices, '2024-11-01');
  assert.equal(result.topCustomers.length, 3);
});

test('dashboard excludes zero-due customers from topCustomers', () => {
  let paid = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  paid = issueInvoice(paid.value, []).value;
  paid = recordPayment(paid, { amount: 6050, date: '2024-10-16' }).value;

  let owed = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  owed = issueInvoice(owed.value, []).value;

  const result = dashboard([paid, owed], '2024-11-01');
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
});

test('dashboard with multiple invoices same customer', () => {
  let inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result = dashboard([inv1, inv2], '2024-11-01');
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert.equal(result.topCustomers[0].due, 6050 + 6050);
});

test('dashboard returns correct structure', () => {
  const result = dashboard([], '2024-11-01');
  assert.ok('counts' in result);
  assert.ok('outstanding' in result);
  assert.ok('overdue' in result);
  assert.ok('topCustomers' in result);
  assert.ok('draft' in result.counts);
  assert.ok('issued' in result.counts);
  assert.ok('partially_paid' in result.counts);
  assert.ok('paid' in result.counts);
  assert.ok('count' in result.overdue);
  assert.ok('amount' in result.overdue);
});

